/**
 *
 * DataTableSort is a component that provides sort functionality for a DataTable column.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableSort
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTableSortEvent } from '@primereact/types/headless/datatable';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableSort component.
 */
export type DataTableSortPassThroughType<E> = PassThroughType<DataTableSortInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableSort component.
 */
export interface DataTableSortPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableSortPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
}
/**
 * Defines valid properties in DataTableSort component.
 */
export interface DataTableSortProps extends BaseComponentProps<DataTableSortInstance, unknown, DataTableSortPassThrough> {
    /**
     * The field name to sort by when this sort trigger is clicked.
     * @default undefined
     */
    field?: string | undefined;
}
/**
 * Defines valid state in DataTableSort component.
 */
export interface DataTableSortState {
    /**
     * Whether the associated field is currently sorted.
     */
    isSorted: boolean;
    /**
     * The current sort order of the associated field.
     */
    sortOrder: number;
}
/**
 * Defines the methods and properties exposed by DataTableSort component.
 */
export interface DataTableSortExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableSort component.
 */
export type DataTableSortInstance = ComponentInstance<DataTableSortProps, DataTableSortState, DataTableSortExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableSortEvent`.
 */
export interface DataTableSortEvent extends UseDataTableSortEvent {
}
